// EXPORT CSV
const exportCSV = (filename, columns, rows) => {
  const header = columns.join(";");
  const body = rows.map(r => r.map(c => `"${String(c ?? "").replace(/"/g, '""')}"`).join(";")).join("\n");
  const blob = new Blob(["\uFEFF" + header + "\n" + body], { type: "text/csv;charset=utf-8;" });
  const url = URL.createObjectURL(blob);
  const a = document.createElement("a"); a.href = url; a.download = filename; a.click();
  URL.revokeObjectURL(url);
};

// NOTIFICHE
const getNotifiche = (data) => {
  const alerts = [];
  const sottoscorta = (data.magazzino || []).filter(p => p.giacenza <= p.sogliaMinima);
  if (sottoscorta.length > 0) alerts.push({ tipo: "warning", msg: `⚠ ${sottoscorta.length} prodotti sotto scorta in magazzino`, link: "magazzino" });
  const senzaBolla = (data.ordini || []).filter(o => !o.bolla && o.stato !== "Annullato" && o.stato !== "In attesa");
  if (senzaBolla.length > 0) alerts.push({ tipo: "warning", msg: `📋 ${senzaBolla.length} ordini senza bolla di consegna`, link: "riconciliazione" });
  const creditiAperti = (data.vendite || []).filter(v => v.stato === "In attesa");
  if (creditiAperti.length > 0) alerts.push({ tipo: "info", msg: `💶 ${creditiAperti.length} vendite in attesa di pagamento`, link: "vendite" });
  return alerts;
};

function Pill({ color, children }) {
  const map = { green: "#10b981", red: "#ef4444", yellow: "#f59e0b", blue: "#6366f1", gray: "#64748b", purple: "#a855f7" };
  const c = map[color] || map.gray;
  return <span style={{ background: `${c}22`, color: c, border: `1px solid ${c}44`, borderRadius: 20, padding: "2px 10px", fontSize: 11, fontWeight: 600, letterSpacing: 0.5 }}>{children}</span>;
}

