function Input({ label, value, onChange, type = "text", required, disabled }) {
  return (
    <div style={{ marginBottom: 16 }}>
      <label style={{ display: "block", color: COLORS.textDim, fontSize: 12, fontWeight: 600, marginBottom: 6, letterSpacing: 0.5, textTransform: "uppercase" }}>{label}{required && " *"}</label>
      <input type={type} value={value} onChange={e => onChange(e.target.value)} required={required} disabled={disabled}
        style={{ width: "100%", background: COLORS.surface, border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "10px 14px", color: disabled ? COLORS.textMuted : COLORS.text, fontSize: 14, outline: "none", boxSizing: "border-box", opacity: disabled ? 0.6 : 1 }} />
    </div>
  );
}

