const sbFetch = async (path, options = {}) => {
  const res = await fetch(`${SUPABASE_URL}/rest/v1/${path}`, {
    ...options,
    headers: {
      "Content-Type": "application/json",
      "apikey": SUPABASE_KEY,
      "Authorization": `Bearer ${SUPABASE_KEY}`,
      "Prefer": options.prefer || "return=representation",
      ...options.headers,
    },
  });
  if (!res.ok) { const err = await res.text(); throw new Error(err); }
  const text = await res.text();
  return text ? JSON.parse(text) : null;
};

const sbGet = (table) => sbFetch(`${table}?select=*`);
const sbUpsert = (table, data) => sbFetch(table, { method: "POST", prefer: "resolution=merge-duplicates,return=representation", headers: { "Prefer": "resolution=merge-duplicates,return=representation" }, body: JSON.stringify(data) });
const sbDelete = (table, id) => sbFetch(`${table}?id=eq.${id}`, { method: "DELETE", prefer: "return=minimal" });

// APP ROOT
export default function App() {
  const [utente, setUtente] = useState(null);
  const [tab, setTab] = useState(null);
  const [data, setData] = useState(DEMO_DATA);
  const [syncStatus, setSyncStatus] = useState("idle");
  const [dbReady, setDbReady] = useState(false);

  useEffect(() => {
    if (utente) setTab(utente.ruolo === "admin" ? "dashboard" : "catalogo");
  }, [utente]);

  // LOAD FROM SUPABASE
  useEffect(() => {
    const loadData = async () => {
      setSyncStatus("saving");
      try {
        const [incassi, fornitori, catalogo, templates, merci, ordini, documenti, costi, magazzino, clienti, vendite, cfg] = await Promise.all([
          sbGet("incassi"), sbGet("fornitori"), sbGet("catalogo"), sbGet("templates"),
          sbGet("merci"), sbGet("ordini"), sbGet("documenti"), sbGet("costi"),
          sbGet("magazzino"), sbGet("clienti"), sbGet("vendite"), sbGet("emailjs_config"),
        ]);
        const emailjsConfig = cfg?.[0] ? { serviceId: cfg[0].service_id, templateId: cfg[0].template_id, publicKey: cfg[0].public_key } : DEMO_DATA.emailjsConfig;
        // Parse JSON fields
        const parseSedi = (arr) => (arr || []).map(r => ({ ...r, sedi: typeof r.sedi === "string" ? JSON.parse(r.sedi || "[]") : (r.sedi || []) }));
        const parseRighe = (arr) => (arr || []).map(r => ({ ...r, righe: typeof r.righe === "string" ? JSON.parse(r.righe || "[]") : (r.righe || []) }));
        setData({
          incassi: incassi || [],
          fornitori: parseSedi(fornitori || []),
          catalogo: parseSedi(catalogo || []),
          templates: parseRighe(templates || []),
          merci: merci || [],
          ordini: ordini || [],
          documenti: documenti || [],
          costi: costi || [],
          magazzino: magazzino || [],
          clienti: clienti || [],
          vendite: vendite || [],
          emailjsConfig,
        });
        setDbReady(true);
        setSyncStatus("saved");
        setTimeout(() => setSyncStatus("idle"), 1500);
      } catch (e) {
        console.error("Supabase load error:", e);
        setSyncStatus("error");
        setDbReady(false);
      }
    };
    loadData();
  }, []);

  // SYNC TO SUPABASE: diffing per tabella
  const setDataAndSync = useCallback((updater, table, record) => {
    setData(prev => {
      const next = typeof updater === "function" ? updater(prev) : updater;
      if (dbReady && table && record) {
        setSyncStatus("saving");
        const toSave = { ...record };
        // Serialize array fields to JSON string for Supabase
        if (toSave.sedi && Array.isArray(toSave.sedi)) toSave.sedi = JSON.stringify(toSave.sedi);
        if (toSave.righe && Array.isArray(toSave.righe)) toSave.righe = JSON.stringify(toSave.righe);
        sbUpsert(table, toSave)
          .then(() => { setSyncStatus("saved"); setTimeout(() => setSyncStatus("idle"), 1500); })
          .catch((e) => { console.error(e); setSyncStatus("error"); });
      }
      return next;
    });
  }, [dbReady]);

  const deleteFromDb = useCallback(async (table, id) => {
    if (!dbReady) return;
    try { await sbDelete(table, id); } catch (e) { console.error(e); }
  }, [dbReady]);

  const [menuAperto, setMenuAperto] = useState(false);

  if (!utente) return <Login onLogin={setUtente} />;

  const TABS = utente.ruolo === "admin" ? TABS_ADMIN : TABS_OPERATORE;

  // Unified DB helper passed to all components
  const db = {
    save: (table, record) => {
      setDataAndSync(prev => {
        const arr = prev[table] || [];
        const exists = arr.find(r => r.id === record.id);
        return { ...prev, [table]: exists ? arr.map(r => r.id === record.id ? record : r) : [record, ...arr] };
      }, table, record);
    },
    delete: (table, id) => {
      setDataAndSync(prev => ({ ...prev, [table]: (prev[table] || []).filter(r => r.id !== id) }), null, null);
      deleteFromDb(table, id);
    },
    saveEmailJS: (cfg) => {
      setDataAndSync(prev => ({ ...prev, emailjsConfig: cfg }), "emailjs_config", { id: 1, service_id: cfg.serviceId, template_id: cfg.templateId, public_key: cfg.publicKey });
    },
  };

  const renderTab = () => {
    switch (tab) {
      case "dashboard": return <Dashboard data={data} />;
      case "calendario": return <Calendario data={data} setData={setDataAndSync} db={db} utente={utente} />;
      case "incassi": return <Incassi data={data} setData={setDataAndSync} db={db} utente={utente} />;
      case "clienti": return <Clienti data={data} setData={setDataAndSync} db={db} utente={utente} />;
      case "vendite": return <Vendite data={data} setData={setDataAndSync} db={db} utente={utente} />;
      case "fornitori": return <Fornitori data={data} setData={setDataAndSync} db={db} />;
      case "catalogo": return <CatalogoOrdini data={data} setData={setDataAndSync} db={db} utente={utente} />;
      case "magazzino": return <Magazzino data={data} setData={setDataAndSync} db={db} utente={utente} />;
      case "merci": return <Merci data={data} setData={setDataAndSync} db={db} />;
      case "ordini": return <Ordini data={data} setData={setDataAndSync} db={db} utente={utente} />;
      case "riconciliazione": return <Riconciliazione data={data} />;
      case "costi": return <CostiModule data={data} setData={setDataAndSync} db={db} utente={utente} />;
      case "documenti": return <Documenti data={data} setData={setDataAndSync} db={db} />;
      case "conto": return <ContoEconomico data={data} db={db} utente={utente} />;
      case "utenti": return <GestioneUtenti />;
      default: return null;
    }
  };

  const syncLabel = { saving: "☁ Salvataggio...", saved: "✓ Supabase sync", error: "✗ Errore DB", idle: dbReady ? "🟢 Supabase attivo" : "🔴 DB non connesso" };
  const syncColor = { saving: COLORS.yellow, saved: COLORS.green, error: COLORS.red, idle: dbReady ? COLORS.green : COLORS.red };

  return (
    <div style={{ display: "flex", flexDirection: "column", height: "100vh", background: COLORS.bg, fontFamily: "'Outfit','Segoe UI',sans-serif", color: COLORS.text }}>
      <style>{`
        @import url('https://fonts.googleapis.com/css2?family=Outfit:wght@400;500;600;700&display=swap');
        * { box-sizing: border-box; margin: 0; padding: 0; }
        ::-webkit-scrollbar { width: 6px; }
        ::-webkit-scrollbar-track { background: ${COLORS.bg}; }
        ::-webkit-scrollbar-thumb { background: ${COLORS.border}; border-radius: 3px; }
        .sidebar { width: 225px; background: ${COLORS.surface}; border-right: 1px solid ${COLORS.border}; padding: 28px 16px; display: flex; flex-direction: column; gap: 4; flex-shrink: 0; overflow-y: auto; }
        .main-layout { display: flex; flex: 1; overflow: hidden; }
        .content-area { flex: 1; overflow-y: auto; padding: 32px; }
        .mobile-header { display: none; }
        .mobile-nav { display: none; }
        .sidebar-overlay { display: none; }
        @media (max-width: 768px) {
          .sidebar { display: none; }
          .mobile-header { display: flex; align-items: center; justify-content: space-between; padding: 12px 16px; background: ${COLORS.surface}; border-bottom: 1px solid ${COLORS.border}; flex-shrink: 0; }
          .mobile-nav { display: flex; position: fixed; bottom: 0; left: 0; right: 0; background: ${COLORS.surface}; border-top: 1px solid ${COLORS.border}; z-index: 100; padding: 6px 0; overflow-x: auto; }
          .content-area { padding: 16px; padding-bottom: 80px; }
          .sidebar-overlay { display: block; position: fixed; inset: 0; background: rgba(0,0,0,0.7); z-index: 200; }
          .sidebar-mobile { position: fixed; left: 0; top: 0; bottom: 0; width: 260px; background: ${COLORS.surface}; z-index: 201; padding: 24px 16px; overflow-y: auto; display: flex; flex-direction: column; gap: 4; border-right: 1px solid ${COLORS.border}; }
        }
      `}</style>

      {/* MOBILE HEADER */}
      <div className="mobile-header">
        <button onClick={() => setMenuAperto(true)} style={{ background: "none", border: "none", color: COLORS.text, fontSize: 22, cursor: "pointer", padding: 4 }}>☰</button>
        <div style={{ color: COLORS.accent, fontSize: 13, fontWeight: 800, letterSpacing: 2, textTransform: "uppercase" }}>Gestionale</div>
        <div style={{ color: syncColor[syncStatus], fontSize: 11 }}>{syncStatus === "saving" ? "⏳" : syncStatus === "saved" ? "✓" : syncStatus === "error" ? "✗" : dbReady ? "🟢" : "🔴"}</div>
      </div>

      {/* SIDEBAR OVERLAY MOBILE */}
      {menuAperto && (
        <>
          <div className="sidebar-overlay" onClick={() => setMenuAperto(false)} />
          <div className="sidebar-mobile">
            <div style={{ display: "flex", justifyContent: "space-between", alignItems: "center", marginBottom: 20, paddingBottom: 16, borderBottom: `1px solid ${COLORS.border}` }}>
              <div>
                <div style={{ color: COLORS.accent, fontSize: 11, fontWeight: 800, letterSpacing: 3, textTransform: "uppercase" }}>Gestionale</div>
                <div style={{ color: COLORS.textMuted, fontSize: 11, marginTop: 2 }}>Business Suite</div>
              </div>
              <button onClick={() => setMenuAperto(false)} style={{ background: "none", border: "none", color: COLORS.textMuted, fontSize: 20, cursor: "pointer" }}>✕</button>
            </div>
            {TABS.map(t => (
              <button key={t.id} onClick={() => { setTab(t.id); setMenuAperto(false); }}
                style={{ display: "flex", alignItems: "center", gap: 10, padding: "12px 12px", borderRadius: 10, border: "none", cursor: "pointer", textAlign: "left", width: "100%", background: tab === t.id ? COLORS.accentGlow : "transparent", color: tab === t.id ? COLORS.accentLight : COLORS.textMuted, fontWeight: tab === t.id ? 700 : 500, fontSize: 14, borderLeft: tab === t.id ? `2px solid ${COLORS.accent}` : "2px solid transparent" }}>
                <span style={{ fontSize: 16 }}>{t.icon}</span>{t.label}
              </button>
            ))}
            <div style={{ marginTop: "auto", paddingTop: 16, borderTop: `1px solid ${COLORS.border}` }}>
              <div style={{ color: COLORS.text, fontSize: 13, fontWeight: 600, marginBottom: 4 }}>{utente.nome}</div>
              <div style={{ color: syncColor[syncStatus], fontSize: 11, marginBottom: 12 }}>{syncLabel[syncStatus]}</div>
              <button onClick={() => { setUtente(null); setTab(null); setMenuAperto(false); }}
                style={{ width: "100%", background: "transparent", border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "8px 12px", color: COLORS.textMuted, fontSize: 12, cursor: "pointer" }}>
                ← Esci
              </button>
            </div>
          </div>
        </>
      )}

      <div className="main-layout">
        {/* SIDEBAR DESKTOP */}
        <div className="sidebar">
          <div style={{ padding: "0 8px 20px", borderBottom: `1px solid ${COLORS.border}`, marginBottom: 8 }}>
            <div style={{ color: COLORS.accent, fontSize: 11, fontWeight: 800, letterSpacing: 3, textTransform: "uppercase" }}>Gestionale</div>
            <div style={{ color: COLORS.textMuted, fontSize: 11, marginTop: 2 }}>Business Suite</div>
          </div>
          {getNotifiche(data).map((n, i) => (
            <div key={i} onClick={() => setTab(n.link)}
              style={{ background: n.tipo === "warning" ? `${COLORS.yellow}15` : `${COLORS.blue}15`, border: `1px solid ${n.tipo === "warning" ? COLORS.yellow : COLORS.blue}33`, borderRadius: 8, padding: "7px 10px", fontSize: 11, color: n.tipo === "warning" ? COLORS.yellow : COLORS.blue, cursor: "pointer", marginBottom: 4 }}>
              {n.msg}
            </div>
          ))}
          {TABS.map(t => (
            <button key={t.id} onClick={() => setTab(t.id)}
              style={{ display: "flex", alignItems: "center", gap: 10, padding: "10px 12px", borderRadius: 10, border: "none", cursor: "pointer", textAlign: "left", width: "100%", background: tab === t.id ? COLORS.accentGlow : "transparent", color: tab === t.id ? COLORS.accentLight : COLORS.textMuted, fontWeight: tab === t.id ? 700 : 500, fontSize: 13, borderLeft: tab === t.id ? `2px solid ${COLORS.accent}` : "2px solid transparent" }}>
              <span style={{ fontSize: 14 }}>{t.icon}</span>{t.label}
            </button>
          ))}
          <div style={{ marginTop: "auto", borderTop: `1px solid ${COLORS.border}`, paddingTop: 16, display: "flex", flexDirection: "column", gap: 8 }}>
            <div style={{ color: syncColor[syncStatus], fontSize: 11, textAlign: "center" }}>{syncLabel[syncStatus]}</div>
            <div style={{ background: COLORS.card, borderRadius: 10, padding: "10px 12px" }}>
              <div style={{ color: COLORS.text, fontSize: 13, fontWeight: 600, marginBottom: 4 }}>{utente.nome}</div>
              <Pill color={utente.ruolo === "admin" ? "purple" : "blue"}>{utente.ruolo === "admin" ? "👑 Admin" : "👤 Operatore"}</Pill>
              {utente.sede && <div style={{ marginTop: 6 }}><Pill color={utente.sede === "Vivandaio" ? "blue" : "green"}>🏠 {utente.sede}</Pill></div>}
            </div>
            <button onClick={() => { setUtente(null); setTab(null); }}
              style={{ width: "100%", background: "transparent", border: `1px solid ${COLORS.border}`, borderRadius: 10, padding: "8px 12px", color: COLORS.textMuted, fontSize: 12, cursor: "pointer" }}>
              ← Esci
            </button>
          </div>
        </div>

        {/* CONTENT */}
        <div className="content-area">{renderTab()}</div>
      </div>

      {/* MOBILE BOTTOM NAV — ultimi 5 tab usati */}
      <div className="mobile-nav">
        {TABS.slice(0, 5).map(t => (
          <button key={t.id} onClick={() => setTab(t.id)}
            style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 2, padding: "6px 12px", border: "none", background: "transparent", color: tab === t.id ? COLORS.accentLight : COLORS.textMuted, cursor: "pointer", flexShrink: 0, minWidth: 60 }}>
            <span style={{ fontSize: 18 }}>{t.icon}</span>
            <span style={{ fontSize: 9, fontWeight: tab === t.id ? 700 : 400 }}>{t.label.split(" ")[0]}</span>
          </button>
        ))}
        <button onClick={() => setMenuAperto(true)}
          style={{ display: "flex", flexDirection: "column", alignItems: "center", gap: 2, padding: "6px 12px", border: "none", background: "transparent", color: COLORS.textMuted, cursor: "pointer", flexShrink: 0, minWidth: 60 }}>
          <span style={{ fontSize: 18 }}>☰</span>
          <span style={{ fontSize: 9 }}>Menu</span>
        </button>
      </div>
    </div>
  );
}
